function check(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function parseUser(body: unknown): { id: number; name: string } {
  check(typeof body === "object" && body !== null, "body is not an object");
  const { id, name } = body as Record<string, unknown>;
  check(typeof id === "number", "id must be a number");
  check(typeof name === "string", "name must be a string");
  return { id, name }; // both narrowed by the assertions above
}
